def server_dispatcher(max_workers=4):
    def worker():
        while True:
            task_id, prompt, max_tokens = query_queue.get()
            if task_id is None:
                break  # Sentinel to shut down
            try:
                result = query_llama_server(prompt, max_tokens)
                query_results[task_id] = result
            except Exception as e:
                query_results[task_id] = f"[Error] {str(e)}"
            query_queue.task_done()

    for _ in range(max_workers):
        t = Thread(target=worker, daemon=True)
        t.start()
def load_tokenizer():
