def get_tokenizer():
    global _tokenizer
    if _tokenizer is None:
        _tokenizer = load_tokenizer()
    return _tokenizer
def count_tokens(llm, text: str) -> int:
    return len(llm.tokenize(text.encode("utf-8")))
def split_by_tokens(llm, text: str, max_tokens: int):
    tokens = llm.tokenize(text.encode("utf-8"), add_bos=False)
    chunks = []
    start = 0
    while start < len(tokens):
        end = min(start + max_tokens, len(tokens))
        chunk_tokens = tokens[start:end]
        chunk_text = llm.detokenize(chunk_tokens).decode("utf-8", errors="ignore")
        chunks.append(chunk_text.strip())
        start = end
    return chunks
def query_llama_server(prompt, max_tokens=1024, retries=3):
    delay = 1
    timeout = 40
    for attempt in range(retries):
        try:
            response = session.post(
                "http://localhost:8080/completion",
                json={
                    "prompt": prompt,
                    "stop": ["###"],
                    "n_predict": max_tokens,
                    "temperature": 0.2,
                    "top_k": 40,
                    "top_p": 0.95
                },
                timeout=timeout 
            )
            response.raise_for_status()
            return response.json()["content"].strip()
        except Exception as e:
            print(f"Retry {attempt+1} failed: {e}")
            time.sleep(delay)
            delay *= 2
    raise RuntimeError("Failed to query llama-server after 3 retries.")
