def summarize_worker(file_list, worker_id):
    import time
    time.sleep(worker_id * 0.5)
    failed = []
    llm = get_tokenizer()

    for rel_path in tqdm(file_list, desc=f"Worker {worker_id} summarizing"):
        input_file = CHUNK_DIR / rel_path

        # Skip large files
        if input_file.stat().st_size > MAX_FILE_SIZE_BYTES:
            print(f"⏩ [Worker {worker_id}] Skipping large file: {rel_path}")
            continue

        output_file = SUMMARY_DIR / rel_path.with_suffix(".summary.json")
        if output_file.exists() or input_file.stat().st_size < 50:
            continue

        combined_summary = ""

        try:
            with open(input_file, 'r', encoding='utf-8') as f:
                for i, line in enumerate(f):
                    try:
                        chunk = json.loads(line)["code"]
                        prompt = make_summary_prompt(chunk)
                        prompt_tokens = count_tokens(llm, prompt)
                        safe_n_predict = max(256, MAX_CTX - prompt_tokens - 256)

                        if safe_n_predict <= 0:
                            print(f"⛔ [Worker {worker_id}] Skipping chunk {i} in {rel_path} — exceeds context window")
                            failed.append(f"{rel_path} [chunk {i} skipped: too large]")
                            continue

                        task_id = f"{rel_path}-{i}"
                        query_queue.put((task_id, prompt, min(MAX_TOKENS, safe_n_predict)))
                        while task_id not in query_results:
                            time.sleep(0.01)
                        summary = query_results.pop(task_id)

                        time.sleep(0.05)
                        combined_summary += f"\n[Chunk {i}]\n{summary}\n"
                        if i % 20 == 0:
                            gc.collect()

                    except Exception as e:
                        print(f"⚠️ [Worker {worker_id}] Error summarizing chunk {i} of {rel_path}: {e}")
                        failed.append(f"{rel_path} [chunk {i}]")

        except Exception as e:
            print(f"⚠️ [Worker {worker_id}] Failed to read {rel_path}: {e}")
            failed.append(str(rel_path))
            continue

        output_file.parent.mkdir(parents=True, exist_ok=True)
        if combined_summary.strip():
            with open(output_file, 'w', encoding='utf-8') as f:
                json.dump({"file": str(rel_path), "summary": combined_summary.strip()}, f, indent=2)
            print(f"✅ [Worker {worker_id}] {rel_path} summarized")
        else:
            print(f"⚠️ [Worker {worker_id}] Skipped writing empty summary for {rel_path}")
            failed.append(f"{rel_path} [empty summary]")

    if failed:
        with open(FAILED_LOG, 'a', encoding='utf-8') as flog:
            flog.write("\n".join(failed) + "\n")

def split_workload
:
    all_jsonl = sorted(CHUNK_DIR.rglob("*.jsonl"), key=lambda f: f.stat().st_size)
